#include <stdio.h>
#include <stdlib.h>

typedef struct BSTNode
{
    int key;
    struct BSTNode *lchild, *rchild;
} BSTNode, *BSTree;


int InsertBST(BSTree *T, int key)
{
    if (*T == NULL)
    {
        *T = (BSTree)malloc(sizeof(BSTNode));
        (*T)->key = key;
        (*T)->lchild = (*T)->rchild = NULL;
        return 1;
    }
    if (key == (*T)->key)
        return 0;
    if (key < (*T)->key)
        return InsertBST(&(*T)->lchild, key);
    return InsertBST(&(*T)->rchild, key);
}

void PreOrder(BSTree T)
{
    if (T != NULL)
    {
        printf("%d ", T->key);
        PreOrder(T->lchild);
        PreOrder(T->rchild);
    }
}

void InOrder(BSTree T)
{
    if (T != NULL)
    {
        InOrder(T->lchild);
        printf("%d ", T->key);
        InOrder(T->rchild);
    }
}

int Depth(BSTree T)
{
    int dl, dr;

    if (T == NULL)
        return 0;
    dl = Depth(T->lchild);
    dr = Depth(T->rchild);
    return (dl > dr ? dl : dr) + 1;
}

