#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode
{
    int data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按扩展先序序列递归建树 */
BiTree Create(void)
{
    int x;
    BiTree t;

    if (scanf("%d", &x) != 1)
        return NULL;
    if (x == -1)
        return NULL;
    t = (BiTree)malloc(sizeof(BiTNode));
    t->data = x;
    t->lchild = Create();
    t->rchild = Create();
    return t;
}

/* 中序遍历过程中用 *prev 记录前驱值，一次遍历完成判定 */
int IsBST(BiTree T, int *prev)
{
    if (T == NULL)
        return 1;
    if (!IsBST(T->lchild, prev))
        return 0;
    if (T->data <= *prev)
        return 0;
    *prev = T->data;
    return IsBST(T->rchild, prev);
}

int Count(BiTree T)
{
    if (T == NULL)
        return 0;
    return Count(T->lchild) + Count(T->rchild) + 1;
}

int main(void)
{
    BiTree T;
    int prev = -100000, n;

    T = Create();
    n = Count(T);
    if (IsBST(T, &prev))
        printf("YES %d\n", n);
    else
        printf("NO %d\n", n);
    return 0;
}

