#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode
{
    int data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按扩展先序序列递归建树 */
BiTree Create(void)
{
    int x;
    BiTree t;

    if (scanf("%d", &x) != 1)
        return NULL;
    if (x == -1)
        return NULL;
    t = (BiTree)malloc(sizeof(BiTNode));
    t->data = x;
    t->lchild = Create();
    t->rchild = Create();
    return t;
}

/* 后序遍历求高度：一旦发现子树不平衡立即用 -1 作为"不平衡"标记上传 */
int BalHeight(BiTree T)
{
    int hl, hr;

    if (T == NULL)
        return 0;
    hl = BalHeight(T->lchild);
    if (hl == -1)
        return -1;
    hr = BalHeight(T->rchild);
    if (hr == -1)
        return -1;
    if (hl - hr > 1 || hr - hl > 1)
        return -1;
    return (hl > hr ? hl : hr) + 1;
}

int Height(BiTree T)
{
    int hl, hr;

    if (T == NULL)
        return 0;
    hl = Height(T->lchild);
    hr = Height(T->rchild);
    return (hl > hr ? hl : hr) + 1;
}

int main(void)
{
    BiTree T;
    int h;

    T = Create();
    h = BalHeight(T);
    if (h == -1)
        printf("UNBAL %d\n", Height(T));
    else
        printf("BAL %d\n", h);
    return 0;
}

