#include <stdio.h>
#include <stdlib.h>

#define M 11

typedef struct Node
{
    int key;
    struct Node *next;
} Node;

int Hash(int key)
{
    return key % M;
}

/* 头插法把 key 加入同义词链 */
void Insert(Node *ht[], int key)
{
    Node *p = (Node *)malloc(sizeof(Node));

    p->key = key;
    p->next = ht[Hash(key)];
    ht[Hash(key)] = p;
}

/* 查找成功返回该关键字在链中的序号（从 1 开始计数），失败返回 0 */
int Search(Node *ht[], int key)
{
    Node *p;
    int c = 0;

    for (p = ht[Hash(key)]; p != NULL; p = p->next)
    {
        c++;
        if (p->key == key)
            return c;
    }
    return 0;
}

int main(void)
{
    Node *ht[M];
    int n, q, i, x;

    for (i = 0; i < M; i++)
        ht[i] = NULL;
    if (scanf("%d", &n) != 1 || n < 0 || n > 100)
        return 1;
    for (i = 0; i < n; i++)
    {
        if (scanf("%d", &x) != 1)
            return 1;
        Insert(ht, x);
    }
    if (scanf("%d", &q) != 1 || q < 0 || q > 20)
        return 1;
    for (i = 0; i < q; i++)
    {
        if (scanf("%d", &x) != 1)
            return 1;
        printf("%d\n", Search(ht, x));
    }
    return 0;
}

